using namespace ark;using V=arkjson::Value;namespace fs=std::filesystem;
static void check(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
static V parse(const std::string& text){V v;check(arkjson::parse(text,v),"fixture JSON");return v;}
static V call(AgentSession& s,const char* tool,V args=V::makeObj()){auto out=s.call(tool,args);if(out.find("isError")->b)throw std::runtime_error(std::string(tool)+": "+out.find("structuredContent")->dump());return *out.find("structuredContent");}
static V apply(AgentSession& s,const std::string& commands){V args=V::makeObj();args.set("commands",parse(commands));args.set("expected_revision",V::makeNum((double)s.revision));return call(s,"doc_apply",args);}
static double area(const Mesh& mesh){double value=0;for(size_t i=0;i<mesh.idx.size();i+=3){auto vertex=[&](u32 index){size_t at=(size_t)index*3;return Vec3{mesh.pos[at],mesh.pos[at+1],mesh.pos[at+2]};};auto a=vertex(mesh.idx[i]),b=vertex(mesh.idx[i+1]),c=vertex(mesh.idx[i+2]);value+=(b-a).cross(c-a).len()*.5;}return value;}
static Sketch sketch(const std::string& text){Sketch sk;std::string error;check(sketchFromJson(text,sk,&error),"sketch fixture");return sk;}
static void regions(){
    auto closed=sketch(R"JSON({"entities":[{"kind":"line","dof":[0,0,10,0]},{"kind":"line","dof":[10,0,10,10]},{"kind":"line","dof":[10,10,0,10]},{"kind":"line","dof":[0,10,0,0]},{"kind":"line","dof":[20,0,30,0]}]})JSON");
    check(std::abs(area(sketchRegionMesh(closed,Mat4{}))-100)<1e-5,"closed region with independent open line shades correctly");closed.ents[3].dof[3]=1;check(sketchRegionMesh(closed,Mat4{}).idx.empty(),"open chain never shades");
    auto nested=sketch(R"JSON({"entities":[{"kind":"wire","start":[0,0],"segments":[{"kind":"line","to":[20,0]},{"kind":"line","to":[20,20]},{"kind":"line","to":[0,20]},{"kind":"line","to":[0,0]}]},{"kind":"wire","start":[5,5],"segments":[{"kind":"line","to":[15,5]},{"kind":"line","to":[15,15]},{"kind":"line","to":[5,15]},{"kind":"line","to":[5,5]}]}]})JSON");
    check(std::abs(area(sketchRegionMesh(nested,Mat4::rotX(.7)))-300)<1e-4,"nested hole remains empty on rotated plane");nested.ents[1].construction=true;check(std::abs(area(sketchRegionMesh(nested,Mat4{}))-400)<1e-5,"construction curves do not carve regions");
    auto crossed=sketch(R"JSON({"entities":[{"kind":"wire","start":[0,0],"segments":[{"kind":"line","to":[10,10]},{"kind":"line","to":[0,10]},{"kind":"line","to":[10,0]},{"kind":"line","to":[0,0]}]}]})JSON");check(sketchRegionMesh(crossed,Mat4{}).idx.empty(),"self intersection never shades");
    NamedSketch circle;circle.sk=sketch(R"JSON({"entities":[{"name":"ring","kind":"circle","construction":true,"dof":[0,0,"R"]},{"name":"inset","kind":"offset","source":"ring","distance":"D"}]})JSON");ExprEnv env;env.vars={{"R",100},{"D",2}};evaluateSketch(circle,env);check(circle.error.empty()&&circle.sk.ents[1].segments.size()==2&&circle.sk.ents[1].segments[0].kind==SketchEnt::WireSeg::Arc,"circle offset retains exact analytic arcs instead of polygon segment cap");check(std::abs(circle.sk.ents[1].dof[0]-98)<1e-8,"positive circle offset goes to left/inward");env.vars["D"]=-3;evaluateSketch(circle,env);check(circle.error.empty()&&std::abs(circle.sk.ents[1].dof[0]-103)<1e-8,"signed offset recomputes from source");env.vars["D"]=101;evaluateSketch(circle,env);check(!circle.error.empty(),"collapsed circle offset rejects");
}
static void equation(){ExprEnv env;env.vars={{"R",10},{"H",2}};auto spec=parse(R"JSON({"op":"equation","x":"R*cos(t)","y":"R*sin(t)","z":"H*t","t0":0,"t1":"pi","samples":33})JSON");auto request=sampleEquationCurve(spec,env);const auto& points=request.find("points")->arr;check(request.find("equation_source")->find("authored_samples")->num==33&&points.size()>=33&&request.find("parameters")->arr.size()==points.size()&&std::abs(points.front().arr[0].num-10)<1e-8&&std::abs(points.back().arr[2].num-2*K_PI)<1e-8,"XYZ equation preserves authored sample count, explicit parameter stations and independent coordinates");spec.set("samples",V::makeNum(4));spec.set("tolerance",V::makeNum(.001));request=sampleEquationCurve(spec,env);check(request.find("points")->arr.size()>4&&request.find("equation_evidence")->find("observed_max_chord_error_mm")->num<=.001&&!request.find("equation_evidence")->find("equation_between_samples_bound_verified")->b,"Adaptive source sampling records measured chord accuracy without a global bound");spec.set("samples",V::makeNum(1));bool rejected=false;try{sampleEquationCurve(spec,env);}catch(...){rejected=true;}check(rejected,"invalid sample count rejected");}
static void sources(){auto report=parseComponentWebSearch(R"JSON(<html><a class="result__a" href="//duckduckgo.com/l/?uddg=https%3A%2F%2Fsupplier.example%2Fproduct%3Fid%3D1%26size%3D2&amp;rut=x">Motor A &amp; B</a><a class="result__a" href="http://insecure.example/product">Unsafe</a></html>)JSON","motor");check(report.find("items")->arr.size()==1&&report.find("items")->arr[0].find("sourcing_status")->str=="candidate","web candidates never claim selected sourcing");check(report.find("items")->arr[0].find("source_url")->str=="https://supplier.example/product?id=1&size=2","canonical supplier URL decoded");const auto text=componentPageText("<html>Product <script>send_secret()</script><style>hide</style><p>ABC-123</p></html>");check(text.find("ABC-123")!=std::string::npos&&text.find("secret")==std::string::npos&&text.find("hide")==std::string::npos,"page extraction omits executable and styling content");}
static void sourceQualityRegression(){
    Document source;Feature curve;curve.id=1;curve.type=FeatureType::Curve;curve.nativeSpec=parse(R"JSON({"op":"equation","x":"t","y":"0","z":"0","t0":0,"t1":10,"samples":4})JSON");curve.name="Equation";source.addFeature(curve);auto persisted=parse(documentToJson(source,false,false));check(persisted.find("version")->num<34,"Legacy equation source keeps its compatible document version");source.features[0].nativeSpec.set("tolerance",V::makeNum(.01));persisted=parse(documentToJson(source,false,false));check(persisted.find("version")->num==34,"New adaptive tolerance source selects document format34");Document restored;std::string error;if(!documentFromJson(persisted.dump(),restored,&error))throw std::runtime_error("Adaptive tolerance roundtrip: "+error);persisted.set("version",V::makeNum(33));check(!documentFromJson(persisted.dump(),restored,&error)&&error.find("version 34")!=std::string::npos,"Downgraded adaptive source rejects explicitly");
    auto report=parseComponentWebSearch(R"JSON(<a class="result__a" href="https://browser.example/chrome">Chrome download</a><a class="result__a" href="https://supplier.example/MGN12H">MGN12H linear guide specifications</a><a class="result__a" href="https://amazon.example/">Amazon homepage</a>)JSON","Amazon MGN12H");
    check(report.find("items")->arr.size()==1&&report.find("irrelevant_results_omitted")->num==2,"irrelevant browser and marketplace homepages cannot pass as component candidates");
    bool rejected=false;try{parseComponentWebSearch(R"JSON(<a class="result__a" href="https://browser.example/chrome">Chrome download</a>)JSON","MGN12H");}catch(...){rejected=true;}check(rejected,"all irrelevant results reject explicitly");
    rejected=false;try{parseComponentSourcePage("<script>renderProduct()</script>","https://supplier.example/item","https://supplier.example/item");}catch(...){rejected=true;}check(rejected,"empty JavaScript-only page cannot provide sourcing evidence");
    auto page=parseComponentSourcePage("<h1>MGN12H</h1><p>Guide rail specifications</p>","https://supplier.example/item","https://supplier.example/item");check(!page.find("text")->str.empty(),"readable product evidence is retained");
}
static void queryDiscovery(){
    AgentSession s;s.suppressIterationHistory();auto out=call(s,"query_batch",parse(R"JSON({"queries":[{"tool":"library_sources","args":{},"fields":["sources"]},{"tool":"library_info","args":{}}]})JSON"));check(out.find("results")->arr.size()==2,"library inspection can be batched without writes");auto bad=call(s,"query_batch",parse(R"JSON({"queries":[{"tool":"doc_info","args":{},"fields":["guessed_clearance"]}]})JSON"));const auto& row=bad.find("results")->arr[0];check(row.find("isError")->b&&row.find("structuredContent")->find("error_code")->str=="QUERY_BATCH_FIELD_MISSING"&&row.find("structuredContent")->find("observed_result")&&bad.find("error_count")->num==1,"missing result fields retain observed evidence in an explicit individual error row");
}
static void batch(){
    AgentSession s;s.suppressIterationHistory();apply(s,R"JSON([{"op":"bom.initialize"},{"op":"feature.add","type":"box","name":"First","p":{"dx":10,"dy":10,"dz":10},"part":{"part_number":"A/B","description":"Made box","procurement":"make"}},{"op":"feature.add","type":"box","name":"Second","p":{"dx":5,"dy":5,"dz":5},"part":{"part_number":"Bought","description":"Envelope","procurement":"buy"}},{"op":"assembly.add","feature":1,"name":"One"},{"op":"assembly.add","feature":1,"name":"Hidden","visible":false},{"op":"assembly.add","feature":2,"name":"Two","p":{"tx":30}}])JSON");
    const auto directory=fs::temp_directory_path()/("ark-batch-tests-"+newBomDocumentId());fs::create_directory(directory);struct Cleanup{fs::path p;~Cleanup(){std::error_code e;fs::remove_all(p,e);}} cleanup{directory};V args=parse("{\"expected_revision\":"+std::to_string(s.revision)+",\"formats\":[\"stl\",\"obj\"]}");args.set("path",V::makeStr((directory/"all").string()));const auto revision=s.revision;auto out=call(s,"bom_export_parts",args);check(s.revision==revision&&out.find("files")->arr.size()==4&&out.find("definition_count")->num==2,"one export per counted definition and format without revision change");check(out.find("files")->arr.front().find("quantity")->num==2,"hidden BOM occurrence contributes quantity");check(fs::exists(directory/"all"/"manifest.json")&&fs::exists(directory/"all"/"bom.json"),"batch contains full BOM and manifest");check(s.call("bom_export_parts",args).find("isError")->b,"existing batch never overwritten");
    args.set("path",V::makeStr((directory/"buy").string()));args.set("procurement",V::makeStr("buy"));out=call(s,"bom_export_parts",args);check(out.find("definition_count")->num==1&&out.find("files")->arr[0].find("feature")->num==2,"procurement selects BOM definitions");
    args.set("path",V::makeStr((directory/"invalid").string()));args.set("formats",parse(R"JSON(["stl","dxf"])JSON"));check(s.call("bom_export_parts",args).find("isError")->b&&!fs::exists(directory/"invalid"),"failed second format publishes no partial batch");for(const auto& entry:fs::directory_iterator(directory))check(entry.path().filename().string().rfind(".ark-batch-",0)!=0,"failed staging cleaned");
    args.set("expected_revision",V::makeNum((double)revision-1));check(s.call("bom_export_parts",args).find("isError")->b,"stale batch rejected before writing");
}
